/* engines/aplayer.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "../context.js";

export function install(P) {


  function engineHost(id) {
    let host = document.getElementById(id);
    if (!host) {
      host = document.createElement("div");
      host.id = id;
      host.setAttribute("aria-hidden", "true");
      host.style.cssText = "position:absolute;left:-99999px;top:0;width:320px;height:120px;visibility:hidden;pointer-events:none;";
      document.body.appendChild(host);
    }
    return host;
  }

  function aplayerTrack(url) {
    return {
      name: P.state.current?.title || "zqwy",
      artist: "zqwy",
      url,
      cover: P.state.current?.cover ? P.assetUrl(P.state.current.cover) : undefined,
    };
  }

  /* APlayer normally owns a hidden <audio>. Creating it while
     document.createElement('audio') returns our shared element makes APlayer
     the component driving that element instead. */
  async function createAPlayer(url, startAt, autoplay) {
    try { await P.loadAPlayerScript(); } catch {
      P.fallbackToHtml5();
      P.notify("engine");
      return false;
    }
    if (!window.APlayer) {
      P.fallbackToHtml5();
      P.notify("engine");
      return false;
    }

    P.showEngineUi("aplayer");
    const track = P.aplayerTrack(url);
    try {
      if (!P.aplayer) {
        // Render APlayer's own UI in the player's seek row. It still receives
        // the shared <audio> via the createElement shim, so its controls drive
        // the real playback.
        P.aplayerHost = P.$("labAPlayer") || P.engineHost("zqwy-aplayer-host");
        const position = P.rememberAudioDom();
        P.aplayer = P.withSharedAudioElement(() => new window.APlayer({
          container: P.aplayerHost,
          audio: [track],
          autoplay: false,
          theme: "#ffffff",
          loop: "none",
          order: "none",
          // Auto preload lets the shared element report real progress to the
          // loading indicator even when the track isn't auto-playing.
          preload: "auto",
          listFolded: true,
        }));
        P.restoreAudioDom(position);
      } else {
        P.aplayer.list.audios = [track];
        P.aplayer.setAudio(track);
      }
      P.aplayer.volume(P.state.volume, true);
    } catch {
      P.aplayer = null;
      P.fallbackToHtml5();
      P.notify("engine");
      return false;
    }
    if (startAt) P.setTime(startAt);
    if (autoplay) P.attemptPlay();
    return true;
  }
  Object.assign(P, { engineHost, aplayerTrack, createAPlayer });
}
